func runReplicationSlots(flags rootFlags) error {
	c, err := flags.newClient()
	if err != nil {
		return err
	}
	defer c.Close()

	ctx := context.Background()

	// Query pg_replication_slots for slot inventory
	query := `
SELECT
  slot_name,
  slot_type,
  datname,
  plugin,
  active,
  restart_lsn::text,
  confirmed_flush_lsn::text
FROM pg_replication_slots
ORDER BY slot_name
`

	rows, err := c.Query(ctx, query)
	if err != nil {
		return apiErr("failed to query replication slots: %v", err)
	}
	defer rows.Close()

	type SlotInfo struct {
		SlotName          string  `json:"slot_name"`
		SlotType          string  `json:"slot_type"`
		Database          string  `json:"database"`
		Plugin            *string `json:"plugin"`
		Active            bool    `json:"active"`
		RestartLSN        string  `json:"restart_lsn"`
		ConfirmedFlushLSN *string `json:"confirmed_flush_lsn"`
		WALRetention      string  `json:"wal_retention"` // in bytes, human-readable
	}

	var slots []SlotInfo
	for rows.Next() {
		var (
			slotName          string
			slotType          string
			datname           *string
			plugin            *string
			active            bool
			restartLSN        string
			confirmedFlushLSN *string
		)

		if err := rows.Scan(&slotName, &slotType, &datname, &plugin, &active, &restartLSN, &confirmedFlushLSN); err != nil {
			return apiErr("failed to scan slot row: %v", err)
		}

		slot := SlotInfo{
			SlotName:          slotName,
			SlotType:          slotType,
			Plugin:            plugin,
			Active:            active,
			RestartLSN:        restartLSN,
			ConfirmedFlushLSN: confirmedFlushLSN,
		}
		if datname != nil {
			slot.Database = *datname
		}

		// Calculate WAL retention (bytes between restart_lsn and current WAL position)
		retention, err := getWALRetention(ctx, c, restartLSN)
		if err == nil {
			slot.WALRetention = formatBytes(retention)
		} else {
			slot.WALRetention = "unknown"
		}

		slots = append(slots, slot)
	}

	if err = rows.Err(); err != nil {
		return apiErr("error iterating slot rows: %v", err)
	}

	// Check disk space and warn if retention exceeds available
	warning := ""
	_, _ = getAvailableDiskSpace(ctx, c) // attempt to get disk free, but don't fail if unavailable
	for _, slot := range slots {
		if containsString(slot.WALRetention, []string{"GB", "TB"}) {
			// Simple heuristic: if slot retention is multi-GB, warn about capacity
			warning = "replication slot retention approaching disk capacity"
			break
		}
	}

	result := map[string]interface{}{
		"count": len(slots),
		"slots": slots,
	}
	if warning != "" {
		result["warning"] = warning
	}

	return flags.outputResult(result)
}

// replication monitor - continuous watch mode
func newReplicationMonitorCmd(flags rootFlags) *cobra.Command {
	var interval int

	cmd := &cobra.Command{
		Use:   "monitor [interval-seconds]",
		Short: "Continuous watch mode for replication status",
		Long: `Monitor replication status continuously, updating every N seconds.

Shows replica lag trends and state changes in real-time.
Interval defaults to 5 seconds; use argument to override.

Examples:
  postgresql-admin-pp-cli replication monitor           # Update every 5 seconds
  postgresql-admin-pp-cli replication monitor 10        # Update every 10 seconds
  postgresql-admin-pp-cli replication monitor 1         # Update every 1 second (verbose)`,
		SilenceUsage: true,
		Args:         cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) > 0 {
				_, err := fmt.Sscanf(args[0], "%d", &interval)
				if err != nil || interval < 1 {
					return usageErr("interval must be a positive integer (seconds)")
				}
			}
			if interval == 0 {
				interval = 5 // default
			}
			return runReplicationMonitor(flags, interval)
		},
	}

	return cmd
}

func runReplicationMonitor(flags rootFlags, intervalSeconds int) error {
	c, err := flags.newClient()
	if err != nil {
		return err
	}
	defer c.Close()

	fmt.Printf("Monitoring replication (interval: %ds). Press Ctrl+C to stop.\n", intervalSeconds)
	fmt.Printf("Time\t\t\tReplica\t\tState\t\tLag\n")
	fmt.Println(strings.Repeat("-", 80))

	ticker := time.NewTicker(time.Duration(intervalSeconds) * time.Second)
	defer ticker.Stop()

	for {
		ctx := context.Background()

		// Query current replication status
		query := `
SELECT
  application_name,
  state,
  pg_wal_lsn_diff(pg_current_wal_lsn(), replay_lsn)::bigint as lag_bytes,
  replay_lag::text as lag_text
FROM pg_stat_replication
ORDER BY application_name
`

		rows, err := c.Query(ctx, query)
		if err != nil {
			fmt.Printf("[%s] Error querying replication: %v\n", time.Now().Format("15:04:05"), err)
			<-ticker.C
			continue
		}

		found := false
		for rows.Next() {
			found = true
			var appName, state, lagText string
			var lagBytes int64

			if err := rows.Scan(&appName, &state, &lagBytes, &lagText); err != nil {
				fmt.Printf("[%s] Error scanning row: %v\n", time.Now().Format("15:04:05"), err)
				continue
			}

			lagDisplay := lagText
			if lagDisplay == "" {
				lagDisplay = fmt.Sprintf("%d bytes", lagBytes)
			}

			fmt.Printf("[%s]\t%s\t\t%s\t\t%s\n",
				time.Now().Format("15:04:05"),
				appName,
				state,
				lagDisplay,
			)
		}

		rows.Close()

		if !found {
			fmt.Printf("[%s] No connected replicas\n", time.Now().Format("15:04:05"))
		}

		<-ticker.C
	}
}

// Helper functions

// checkWALLevel verifies that WAL level is set to replica or logical
func checkWALLevel(ctx context.Context, c *client.Client) (string, error) {
	var walLevel string
	err := c.QueryRow(ctx, "SELECT current_setting('wal_level')").Scan(&walLevel)
	if err != nil {
		return "", fmt.Errorf("failed to query WAL level: %v", err)
	}
	return walLevel, nil
}

// getSyncStandbyNames retrieves the synchronous_standby_names setting
func getSyncStandbyNames(ctx context.Context, c *client.Client) (string, error) {
	var syncStandbyNames string
	err := c.QueryRow(ctx, "SELECT current_setting('synchronous_standby_names')").Scan(&syncStandbyNames)
	if err != nil {
		return "", err
	}
	return syncStandbyNames, nil
}

// countExpectedSyncReplicas parses synchronous_standby_names to determine expected count
func countExpectedSyncReplicas(syncStandbyNames string) int {
	// Simple parser: "2 (replica1, replica2, replica3)" means 2 expected
	// or "FIRST 2 (replica1, replica2, replica3)" means 2 expected
	if syncStandbyNames == "" || syncStandbyNames == "*" {
		return 0
	}

	// Try to extract number after "FIRST" or at the start
	var count int
	// Try "FIRST N" format
	if _, err := fmt.Sscanf(syncStandbyNames, "FIRST %d", &count); err == nil {
		return count
	}
	// Try leading number format
	if _, err := fmt.Sscanf(syncStandbyNames, "%d", &count); err == nil {
		return count
	}
	// Default to 1 if format is unrecognized
	return 1
}

// getWALRetention calculates bytes retained by a slot
func getWALRetention(ctx context.Context, c *client.Client, restartLSN string) (int64, error) {
	var retention int64
	query := fmt.Sprintf(
		"SELECT pg_wal_lsn_diff(pg_current_wal_lsn(), '%s'::pg_lsn)::bigint",
		restartLSN,
	)
	err := c.QueryRow(ctx, query).Scan(&retention)
	if err != nil {
		return 0, err
	}
	return retention, nil
}

// getAvailableDiskSpace returns available disk space in bytes
func getAvailableDiskSpace(ctx context.Context, c *client.Client) (int64, error) {
	var available int64
	// PostgreSQL doesn't have a built-in function for this, so we return a placeholder
	// In a real implementation, this would use the OS
	return available, fmt.Errorf("disk space monitoring requires OS-level access")
}

// formatBytes converts bytes to human-readable format (B, KB, MB, GB, TB)
func formatBytes(bytes int64) string {
	if bytes < 1024 {
		return fmt.Sprintf("%d B", bytes)
	}
	if bytes < 1024*1024 {
		return fmt.Sprintf("%.2f KB", float64(bytes)/1024)
	}
	if bytes < 1024*1024*1024 {
		return fmt.Sprintf("%.2f MB", float64(bytes)/(1024*1024))
	}
	if bytes < 1024*1024*1024*1024 {
		return fmt.Sprintf("%.2f GB", float64(bytes)/(1024*1024*1024))
	}
	return fmt.Sprintf("%.2f TB", float64(bytes)/(1024*1024*1024*1024))
}

// containsString checks if any of the substrings exist in the target string
func containsString(target string, substrings []string) bool {
	for _, s := range substrings {
		if strings.Contains(target, s) {
			return true
		}
	}
	return false
}
